        $rules = ['required', 'file'];
        $maxFileSize = $driveConfig->maxFileSize();
        if ($maxFileSize > 0) {
            $rules[] = 'max:'.($maxFileSize / 1024);
        }
        $allowedMimes = $driveConfig->allowedMimeTypes();
        if ($allowedMimes !== []) {
            $rules[] = 'mimetypes:'.implode(',', $allowedMimes);
